  1→import { useState } from "react";
  2→import { supabase } from "@/integrations/supabase/client";
  3→import { Card, CardContent } from "@/components/ui/card";
  4→import { Button } from "@/components/ui/button";
  5→import { Input } from "@/components/ui/input";
  6→import { Label } from "@/components/ui/label";
  7→import { toast } from "sonner";
  8→import { Shield, Eye, EyeOff } from "lucide-react";
  9→
 10→const ChangePasswordCard = () => {
 11→  const [newPassword, setNewPassword] = useState("");
 12→  const [confirmPassword, setConfirmPassword] = useState("");
 13→  const [saving, setSaving] = useState(false);
 14→  const [showPassword, setShowPassword] = useState(false);
 15→
 16→  const handleChangePassword = async () => {
 17→    if (newPassword.length < 6) {
 18→      toast.error("Password too short — must be at least 6 characters.");
 19→      return;
 20→    }
 21→    if (newPassword !== confirmPassword) {
 22→      toast.error("Passwords don't match");
 23→      return;
 24→    }
 25→    setSaving(true);
 26→    const { error } = await supabase.auth.updateUser({ password: newPassword });
 27→    if (error) {
 28→      toast.error(error.message);
 29→    } else {
 30→      toast.success("Password updated");
 31→      setNewPassword("");
 32→      setConfirmPassword("");
 33→    }
 34→    setSaving(false);
 35→  };
 36→
 37→  const passwordsMatch = newPassword && confirmPassword && newPassword === confirmPassword;
 38→  const passwordsMismatch = confirmPassword && newPassword !== confirmPassword;
 39→
 40→  return (
 41→    <Card className="overflow-hidden">
 42→      <div className="flex items-center gap-3 px-6 pt-5 pb-2">
 43→        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10">
 44→          <Shield className="h-4.5 w-4.5 text-primary" />
 45→        </div>
 46→        <div>
 47→          <h3 className="text-base font-semibold text-foreground">Change Password</h3>
 48→          <p className="text-xs text-muted-foreground">Update your account password.</p>
 49→        </div>
 50→      </div>
 51→      <CardContent className="px-6 pt-3 pb-5 space-y-4">
 52→        <div className="space-y-2">
 53→          <Label htmlFor="new-password" className="text-sm">New password</Label>
 54→          <div className="relative">
 55→            <Input
 56→              id="new-password"
 57→              type={showPassword ? "text" : "password"}
 58→              placeholder="Min 6 characters"
 59→              value={newPassword}
 60→              onChange={(e) => setNewPassword(e.target.value)}
 61→              className="pr-10"
 62→            />
 63→            <button
 64→              type="button"
 65→              onClick={() => setShowPassword(!showPassword)}
 66→              className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
 67→            >
 68→              {showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
 69→            </button>
 70→          </div>
 71→        </div>
 72→        <div className="space-y-2">
 73→          <Label htmlFor="confirm-password" className="text-sm">Confirm password</Label>
 74→          <Input
 75→            id="confirm-password"
 76→            type={showPassword ? "text" : "password"}
 77→            placeholder="Re-enter password"
 78→            value={confirmPassword}
 79→            onChange={(e) => setConfirmPassword(e.target.value)}
 80→            className={passwordsMismatch ? "border-destructive focus-visible:ring-destructive" : passwordsMatch ? "border-primary/50 focus-visible:ring-primary" : ""}
 81→          />
 82→          {passwordsMismatch && (
 83→            <p className="text-xs text-destructive">Passwords don't match.</p>
 84→          )}
 85→          {passwordsMatch && (
 86→            <p className="text-xs text-primary">Passwords match ✓</p>
 87→          )}
 88→        </div>
 89→        <Button
 90→          onClick={handleChangePassword}
 91→          disabled={saving || !newPassword || !passwordsMatch}
 92→          className="w-full"
 93→        >
 94→          {saving ? "Updating…" : "Update password"}
 95→        </Button>
 96→      </CardContent>
 97→    </Card>
 98→  );
 99→};
100→
101→export default ChangePasswordCard;
