 10→interface UsageLog {
 11→  id: string;
 12→  created_at: string;
 13→  credits_used: number;
 14→  job_id: string | null;
 15→  job_title?: string | null;
 16→}
 17→
 18→const PAGE_SIZE = 10;
 19→
 20→const UsageHistoryCard = () => {
 21→  const { user } = useAuth();
 22→  const [usageLogs, setUsageLogs] = useState<UsageLog[]>([]);
 23→  const [loading, setLoading] = useState(true);
 24→  const [page, setPage] = useState(0);
 25→  const [hasMore, setHasMore] = useState(false);
 26→  const [loadingMore, setLoadingMore] = useState(false);
 27→
 28→  const fetchLogs = async (pageNum: number, append = false) => {
 29→    if (!user) return;
 30→    if (pageNum === 0) setLoading(true);
 31→    else setLoadingMore(true);
 32→
 33→    const { data } = await supabase
 34→      .from("usage_logs")
 35→      .select("id, created_at, credits_used, job_id")
 36→      .eq("user_id", user.id)
 37→      .order("created_at", { ascending: false })
 38→      .range(pageNum * PAGE_SIZE, (pageNum + 1) * PAGE_SIZE - 1);
 39→
 40→    if (data) {
 41→      setHasMore(data.length === PAGE_SIZE);
 42→      const jobIds = [...new Set(data.map(l => l.job_id).filter(Boolean))] as string[];
 43→      let jobTitles: Record<string, string | null> = {};
 44→      if (jobIds.length > 0) {
 45→        const { data: jobs } = await supabase.from("jobs").select("id, title").in("id", jobIds);
 46→        if (jobs) jobs.forEach(j => { jobTitles[j.id] = j.title; });
 47→      }
