 76→          <p className="text-xs text-muted-foreground">Your credit deductions.</p>
 77→        </div>
 78→      </div>
 79→      <CardContent className="px-6 pt-3 pb-5">
 80→        {loading ? (
 81→          <div className="space-y-3">
 82→            {[...Array(4)].map((_, i) => (
 83→              <Skeleton key={i} className="h-12 w-full rounded-lg" />
 84→            ))}
 85→          </div>
 86→        ) : usageLogs.length === 0 ? (
 87→          <div className="text-center py-10">
 88→            <div className="mx-auto mb-3 flex h-12 w-12 items-center justify-center rounded-full bg-accent">
