 90→            </div>
 91→            <p className="text-sm text-muted-foreground">
 92→              No credit usage yet. Start ranking resumes to see your history here.
 93→            </p>
 94→          </div>
 95→        ) : (
 96→          <div className="space-y-1">
 97→            {usageLogs.map((log) => (
