  6→/** Renders HTML embed code and executes any <script> tags within it */
  7→function EmbedRenderer({ html }: { html: string }) {
  8→  const containerRef = useRef<HTMLDivElement>(null);
  9→
 10→  useEffect(() => {
 11→    const el = containerRef.current;
 12→    if (!el) return;
 13→
 14→    const temp = document.createElement("div");
 15→    temp.innerHTML = html;
 16→
 17→    el.innerHTML = "";
 18→    const scripts: HTMLScriptElement[] = [];
 19→    Array.from(temp.childNodes).forEach((node) => {
 20→      if (node instanceof HTMLScriptElement) {
 21→        scripts.push(node);
 22→      } else {
 23→        el.appendChild(node.cloneNode(true));
 24→      }
 25→    });
 26→
 27→    scripts.forEach((orig) => {
 28→      const script = document.createElement("script");
 29→      if (orig.src) {
 30→        script.src = orig.src;
 31→        script.async = orig.async;
 32→      } else {
 33→        script.textContent = orig.textContent;
 34→      }
 35→      el.appendChild(script);
 36→    });
 37→
 38→    return () => {
 39→      el.innerHTML = "";
 40→    };
 41→  }, [html]);
 42→
 43→  return (
 44→    <div
 45→      ref={containerRef}
 46→      className="w-full min-h-[700px] [&>iframe]:w-full [&>iframe]:min-h-[700px] [&>iframe]:border-0"
 47→    />
 48→  );
 49→}
